const byId=id=>document.getElementById(id);
const statuses={A_QUALIFIER:'À qualifier',DISPONIBLE:'Disponible',EN_MISSION:'En mission',INDISPONIBLE:'Indisponible',ARCHIVE:'Archivé'};
const fields=['name','email','role','skills','location','experience','availability','notes','status'];
let token='',page=1,total=0,editing=null,epoch=0;
const editor=byId('editor');
for(const [value,label] of Object.entries(statuses))for(const id of ['editor-status','status']){const o=document.createElement('option');o.value=value;o.textContent=label;byId(id).append(o)}
function notice(message){byId('notice').textContent=message}
async function api(path,options={}){const r=await fetch('/api/admin/consultants'+path,{...options,headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function reset(){editing=null;editor.reset();byId('form-title').textContent='Nouveau consultant'}
function cell(row,value){const td=document.createElement('td');td.textContent=value;row.append(td);return td}
async function load(){const current=++epoch;const d=await api('?'+new URLSearchParams({q:byId('search').value,status:byId('status').value,page}));if(current!==epoch||!token)return;total=d.total;byId('counts').replaceChildren();byId('rows').replaceChildren();for(const [value,label] of Object.entries(statuses)){const box=document.createElement('div');box.className='count';const n=document.createElement('strong');n.textContent=d.counts[value]||0;box.append(n,document.createTextNode(label));byId('counts').append(box)}
for(const item of d.items){const tr=document.createElement('tr');const profile=cell(tr,item.name);const sub=document.createElement('small');sub.textContent=[item.role,item.location,item.experience?item.experience+' ans':''].filter(Boolean).join(' · ');profile.append(sub);cell(tr,item.skills);cell(tr,item.availability||'À préciser');cell(tr,statuses[item.status]);const b=document.createElement('button');b.textContent='Modifier';b.onclick=()=>{editing=item;for(const f of fields)editor.elements[f].value=item[f];byId('form-title').textContent='Modifier le profil';editor.scrollIntoView({block:'start'})};cell(tr,'').append(b);byId('rows').append(tr)}
if(!d.items.length){const tr=document.createElement('tr');cell(tr,'Aucun profil.').colSpan=5;byId('rows').append(tr)}byId('pages').textContent='Page '+page+' · '+total+' profil(s)';byId('prev').disabled=page===1;byId('next').disabled=page*25>=total}
async function refresh(){try{await load()}catch(e){notice(e.message)}}
byId('login-form').onsubmit=async e=>{e.preventDefault();token=byId('token').value;byId('token').value='';page=1;try{await load();byId('login').hidden=true;byId('workspace').hidden=false;notice('Connecté.')}catch(e){token='';notice(e.message)}};
byId('logout').onclick=()=>{epoch++;token='';reset();byId('rows').replaceChildren();byId('counts').replaceChildren();byId('workspace').hidden=true;byId('login').hidden=false;notice('Déconnecté.')};
editor.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(editor));const target=editing;if(target)data.version=target.version;byId('save').disabled=true;try{await api(target?'/'+encodeURIComponent(target.id):'',{method:target?'PATCH':'POST',body:JSON.stringify(data)});if(token){reset();page=1;await load();notice('Profil enregistré.')}}catch(e){notice(e.message)}finally{byId('save').disabled=false}};
byId('cancel').onclick=reset;byId('filter').onsubmit=e=>{e.preventDefault();page=1;refresh()};byId('prev').onclick=()=>{if(page>1){page--;refresh()}};byId('next').onclick=()=>{if(page*25<total){page++;refresh()}};
